-- Feature 25 local synthetic metadata. Every artifact is operator/scope qualified.
CREATE TABLE IF NOT EXISTS evidence_event_scopes (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS evidence_event_adapter_manifests (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_fixture_queries (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,adapter_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,adapter_hash) REFERENCES evidence_event_adapter_manifests(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_feature03_contexts (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_deliveries (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_events (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,event_hash char(64) NOT NULL,source_id text NOT NULL,source_event_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),supersedes_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,event_hash),UNIQUE(operator_test_id,scope_hash,source_id,source_event_id,revision),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes,FOREIGN KEY(operator_test_id,scope_hash,supersedes_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash),CHECK((revision=1 AND supersedes_hash IS NULL) OR (revision>1 AND supersedes_hash IS NOT NULL)));
CREATE TABLE IF NOT EXISTS evidence_event_relations (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,source_event_hash char(64) NOT NULL,target_event_hash char(64) NOT NULL,relation_kind text NOT NULL CHECK(relation_kind IN ('supersedes','retracts','derives','correlates')),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,source_event_hash,target_event_hash,relation_kind),CHECK(source_event_hash<>target_event_hash),FOREIGN KEY(operator_test_id,scope_hash,source_event_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash),FOREIGN KEY(operator_test_id,scope_hash,target_event_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash));
CREATE TABLE IF NOT EXISTS evidence_event_quarantines (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_quality_assessments (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,event_hash char(64),policy_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,event_hash,policy_hash),FOREIGN KEY(operator_test_id,scope_hash,event_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash));
CREATE TABLE IF NOT EXISTS evidence_event_quality_dimensions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,assessment_hash char(64) NOT NULL,dimension text NOT NULL CHECK(dimension IN ('authenticity','completeness','timeliness','sequence_continuity','parser_validity','mapping_certainty','source_reliability','sanitization')),status text NOT NULL CHECK(status IN ('pass','degraded','fail','not_applicable')),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,assessment_hash,dimension),FOREIGN KEY(operator_test_id,scope_hash,assessment_hash) REFERENCES evidence_event_quality_assessments(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_freshness_policies (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_freshness_decisions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,policy_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_materiality_policies (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_materiality_decisions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,policy_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_watermark_transitions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,source_id text NOT NULL,previous_sequence bigint NOT NULL,sequence bigint NOT NULL CHECK(sequence>=previous_sequence),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,source_id,sequence),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_trigger_intents (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,desired_workflow_identity char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,desired_workflow_identity),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_trigger_members (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,trigger_hash char(64) NOT NULL,event_hash char(64) NOT NULL,member_sequence integer NOT NULL CHECK(member_sequence>=0),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,trigger_hash,member_sequence),UNIQUE(operator_test_id,scope_hash,trigger_hash,event_hash),FOREIGN KEY(operator_test_id,scope_hash,trigger_hash) REFERENCES evidence_event_trigger_intents(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,event_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash));
CREATE TABLE IF NOT EXISTS evidence_event_dispatch_observations (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,trigger_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,trigger_hash) REFERENCES evidence_event_trigger_intents(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_replay_manifests (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES evidence_event_scopes);
CREATE TABLE IF NOT EXISTS evidence_event_replay_manifest_events (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,event_hash char(64) NOT NULL,event_sequence integer NOT NULL CHECK(event_sequence>=0),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,manifest_hash,event_sequence),UNIQUE(operator_test_id,scope_hash,manifest_hash,event_hash),FOREIGN KEY(operator_test_id,scope_hash,manifest_hash) REFERENCES evidence_event_replay_manifests(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,event_hash) REFERENCES evidence_event_events(operator_test_id,scope_hash,event_hash));
CREATE TABLE IF NOT EXISTS evidence_event_missing_sources (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,source_id text NOT NULL,state text NOT NULL CHECK(state IN ('missing','non_retainable','complete','closed')),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,manifest_hash,source_id),FOREIGN KEY(operator_test_id,scope_hash,manifest_hash) REFERENCES evidence_event_replay_manifests(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_analytical_manifests (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,replay_manifest_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,replay_manifest_hash) REFERENCES evidence_event_replay_manifests(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_state_snapshots (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,manifest_hash) REFERENCES evidence_event_replay_manifests(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_roots (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,state_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,context_hash char(64) NOT NULL,request_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,request_hash),FOREIGN KEY(operator_test_id,scope_hash,state_hash) REFERENCES evidence_event_state_snapshots(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,manifest_hash) REFERENCES evidence_event_replay_manifests(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,context_hash) REFERENCES evidence_event_feature03_contexts(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_test_center_bundles (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,root_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,root_hash) REFERENCES evidence_event_roots(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS evidence_event_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,root_hash char(64),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS evidence_event_conflicts (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE OR REPLACE FUNCTION evidence_event_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'evidence_event_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY(SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_name LIKE 'evidence_event_%') LOOP EXECUTE format('DROP TRIGGER IF EXISTS evidence_event_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER evidence_event_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION evidence_event_append_only()',t); END LOOP; END $$;
